/**
 * SelectField eval — fixture-driven test (phase 2f medium Stop γ Task 6).
 *
 * Tests the `SelectField` arm of the evaluator. SelectField reads a 1-based
 * fieldIndex from a Tuple value, returning the item at that position.
 *
 * Cost: Fixed(10), charged BEFORE eval-child (Pattern A).
 * Sigma-rust ref: ergotree-interpreter/src/eval/select_field.rs:9-32
 *
 * Fixtures generated by `fixture-gen/src/cmds/ergoscript/eval/select_field.rs`
 * (sigma-rust oracle; byte-equality check).
 *
 * Inline defensive tests cover:
 *   - 'select-field-input-not-tuple': non-Tuple input (hand-built MIR)
 *   - 'select-field-index-out-of-range': OOB fieldIndex on a 2-tuple
 *     (hand-built MIR; sigma-rust SelectField::new rejects OOB at
 *     construction so this is unreachable from parser-produced trees)
 */

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseTree } from '../../src/wire/ergo-tree'
import { evaluate, evaluateWith } from '../../src/eval/evaluate'
import { makeContext } from '../../src/eval/eval-context'
import { hexToBytes, hydrateSValue, captureEvalError, rehydrateEvalOpts } from '../_helpers'

const __dirname = dirname(fileURLToPath(import.meta.url))

interface SelectFieldFixtureEntry {
  name: string
  tree_bytes_hex: string
  opts_json: Record<string, unknown>
  expected_value_json: unknown
  expected_cost: number
  expected_error_code: string | null
}

interface SelectFieldFixtureFile {
  corpus: string
  entries: SelectFieldFixtureEntry[]
}

const FIXTURE_PATH = join(__dirname, '../fixtures/eval/select-field.json')
const fixture: SelectFieldFixtureFile = JSON.parse(readFileSync(FIXTURE_PATH, 'utf-8'))

describe('SelectField eval (phase 2f medium Stop γ Task 6)', () => {
  for (const entry of fixture.entries) {
    it(entry.name, () => {
      const tree = parseTree(hexToBytes(entry.tree_bytes_hex))
      const opts = rehydrateEvalOpts(entry.opts_json)
      const ctx = makeContext(opts)

      if (entry.expected_error_code !== null) {
        const err = captureEvalError(() => evaluateWith(tree, ctx))
        expect(err.code).toBe(entry.expected_error_code)
      } else {
        const result = evaluateWith(tree, ctx)
        expect(result).toEqual(hydrateSValue(entry.expected_value_json))
        expect(ctx.jitCost).toBe(entry.expected_cost)
      }
    })
  }

  it("non-Tuple input throws 'select-field-input-not-tuple'", () => {
    const tree = {
      header: { version: 0 as const, hasSize: false, constantSegregation: false, rawHeader: 0 },
      constants: [] as [],
      constantTypes: [] as [],
      body: {
        tag: 'SelectField' as const,
        input: {
          tag: 'Const' as const,
          tpe: { tag: 'SInt' as const },
          value: { kind: 'Int' as const, value: 5 },
        },
        fieldIndex: 1,
      },
    }
    const err = captureEvalError(() => evaluate(tree))
    expect(err.code).toBe('select-field-input-not-tuple')
  })

  it("OOB fieldIndex throws 'select-field-index-out-of-range'", () => {
    // Hand-built MIR: SelectField(Tuple(Int(5), Int(99)), fieldIndex=3)
    // sigma-rust SelectField::new rejects OOB at construction, so this is
    // unreachable from a parser-produced tree but we can build it directly.
    const tree = {
      header: { version: 0 as const, hasSize: false, constantSegregation: false, rawHeader: 0 },
      constants: [] as [],
      constantTypes: [] as [],
      body: {
        tag: 'SelectField' as const,
        input: {
          tag: 'Tuple' as const,
          items: [
            {
              tag: 'Const' as const,
              tpe: { tag: 'SInt' as const },
              value: { kind: 'Int' as const, value: 5 },
            },
            {
              tag: 'Const' as const,
              tpe: { tag: 'SInt' as const },
              value: { kind: 'Int' as const, value: 99 },
            },
          ],
        },
        fieldIndex: 3,
      },
    }
    const err = captureEvalError(() => evaluate(tree))
    expect(err.code).toBe('select-field-index-out-of-range')
  })
})
